{
  "claims": [
    {
      "claim": "En Suisse, plusieurs dispositions protègent contre la discrimination basée sur la grossesse ou les projets familiaux lors du recrutement.",
      "verdict": "supported"
    },
    {
      "claim": "L'article 3 de la Loi sur l'égalité (LEg) interdit toute discrimination directe ou indirecte fondée sur le sexe dans les rapports de travail, incluant la discrimination basée sur l'état de grossesse, l'accouchement récent ou les projets familiaux.",
      "verdict": "supported"
    },
    {
      "claim": "Les employeurs ne peuvent pas poser de questions concernant la grossesse, les projets d'enfants, la situation familiale actuelle ou future lors d'un entretien d'embauche.",
      "verdict": "supported"
    },
    {
      "claim": "Un refus d'embauche fondé sur la grossesse ou les projets familiaux constitue une discrimination illicite.",
      "verdict": "supported"
    },
    {
      "claim": "Il existe des exceptions très limitées où l'employeur peut poser des questions sur la grossesse ou les projets familiaux, par exemple si les questions sont directement liées à l'aptitude physique à exécuter un travail spécifique (mais uniquement après l'offre d'emploi et si pertinentes pour l'exécution des tâches prévues).",
      "verdict": "supported"
    }
  ],
